mapper.select:
SELECT t.kind,t.previous_revision AS previousRevision,t.revision,t.previous_status AS previousStatus,t.status
FROM annotation_transition t JOIN document_revision_meta m ON m.tenant_id=t.tenant_id AND m.project_id=t.project_id AND m.document_revision=t.document_revision
WHERE t.project_id=#{projectId} AND t.annotation_id=#{annotationId} AND m.document_id=#{documentId}
UNION ALL
SELECT 'REPLY' AS kind,CAST(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.previous_revision')) AS DECIMAL(65,0)) AS previousRevision,
  aggregate_revision AS revision,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.status')) AS previousStatus,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.status')) AS status
FROM outbox_event WHERE aggregate_id=#{annotationId} AND event_type='annotation.replied'
  AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.annotation_id'))=#{annotationId}
  AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.document_id'))=#{documentId}
  AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.revision'))=CAST(aggregate_revision AS CHAR)
ORDER BY revision LIMIT #{historyLimit}

mapper.update:
UPDATE annotation SET revision=revision+1,status=#{status},updated_at=#{now}
WHERE project_id=#{projectId} AND annotation_id=#{annotationId} AND document_revision=#{originalDocumentRevision}
  AND revision=#{expected} AND status=#{parentStatus}
  AND EXISTS(SELECT 1 FROM annotation_effective_anchor e JOIN annotation_anchor k ON k.tenant_id=e.tenant_id AND k.project_id=e.project_id AND k.annotation_id=e.annotation_id AND k.anchor_id=e.anchor_id
    WHERE e.tenant_id=annotation.tenant_id AND e.project_id=annotation.project_id AND e.annotation_id=annotation.annotation_id AND k.document_revision=#{documentRevision})

UPDATE document_head SET revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_id=#{documentId} AND current_document_revision=#{documentRevision}
  AND revision=#{expectedDocumentRevision} AND status<>'SIGNED'
  AND EXISTS(SELECT 1 FROM project p WHERE p.project_id=#{projectId} AND p.status='ACTIVE')

UPDATE document_revision_state SET issue_watermark=issue_watermark+1,revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_revision=#{documentRevision}
  AND issue_watermark=#{issueWatermark} AND evidence_watermark=#{evidenceWatermark}

mapper.select:
SELECT invalidation_id AS invalidationId,review_id AS reviewId,trigger_version AS triggerVersion,reason_code AS reasonCode
FROM review_invalidation WHERE project_id=#{projectId} AND trigger_version=#{documentRevision}
  AND reason_code='ANNOTATION_DECIDED' AND review_id=#{reviewId}

SELECT resource_ref FROM audit_event a WHERE subject_id=#{userId} AND project_id=#{projectId}
  AND action='annotation.decided' AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId} AND trace_id=#{requestId}
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification}
